// §4.3 Localization barrel.
//
// AppLocalizations is generated by `flutter gen-l10n` (configured in
// frontend/l10n.yaml) into lib/l10n/generated/app_localizations.dart from the
// ARB sources next to this file (app_en.arb / app_am.arb / app_om.arb).
// CI regenerates it before `flutter analyze`; the generated directory is
// committed so builds are reproducible without network access.
//
// Widgets should import ONLY this barrel:
//   import 'package:nidaw_app/l10n/l10n.dart';
// then use `context.l10n.requestTitle` or `AppLocalizations.of(context)`.

import 'package:flutter/widgets.dart';
import 'package:hive/hive.dart';

import 'generated/app_localizations.dart';

export 'generated/app_localizations.dart';

/// Locale persistence (§4.3 settings switcher).
///
/// The user's explicit choice is stored under this key in the pre-existing
/// 'settings' Hive box (opened in core/di/injection.dart — no new box, no new
/// dependency). Values: 'en', 'am', 'om', or absent/'system' for following
/// the platform locale.
class LocaleController {
  const LocaleController._();

  static const String settingsBoxName = 'settings';
  static const String _localeKey = 'app_locale';

  /// Locales shipped with the app. Keep in sync with supportedLocales in
  /// main.dart and the ARB files in this directory.
  static const List<Locale> supportedLocales = [
    Locale('en'),
    Locale('am'),
    Locale('om'),
  ];

  /// Resolves a stored code into a concrete [Locale]. Null means "follow the
  /// system locale" (MaterialApp falls back to platform locales).
  static Locale? localeFromCode(String? code) {
    switch (code) {
      case 'en':
        return const Locale('en');
      case 'am':
        return const Locale('am');
      case 'om':
        return const Locale('om');
      default:
        return null;
    }
  }

  /// Reads the persisted preference. Never throws: if Hive is unavailable
  /// (cold-start race), returns null (= system default).
  static String? readSavedCode() {
    try {
      final Box box = Hive.box(settingsBoxName);
      final Object? raw = box.get(_localeKey);
      return raw is String ? raw : null;
    } catch (_) {
      return null;
    }
  }

  /// Persists the preference and notifies any listening root widget so the
  /// MaterialApp rebuilds with the new locale immediately.
  static Future<void> saveCode(String? code) async {
    try {
      final Box box = Hive.box(settingsBoxName);
      if (code == null || code == 'system') {
        await box.delete(_localeKey);
      } else {
        await box.put(_localeKey, code);
      }
    } catch (_) {
      // Persistence failure must not crash the settings screen; the choice
      // still applies for this session via the ValueNotifier below.
    }
    apply.value = localeFromCode(code);
  }

  /// Session-level locale override broadcast. main.dart's NidawApp listens to
  /// this; the settings page writes through saveCode().
  static final ValueNotifier<Locale?> apply =
      ValueNotifier<Locale?>(localeFromCode(readSavedCode()));

  /// Options rendered by the settings language switcher. `nativeLabel` is
  /// intentionally monolingual (language names are shown in their own script
  /// by convention), so it is not an ARB key.
  static const List<LocaleChoice> choices = [
    LocaleChoice(null, 'System default'),
    LocaleChoice('en', 'English'),
    LocaleChoice('am', 'አማርኛ'),
    LocaleChoice('om', 'Afaan Oromoo'),
  ];
}

/// One row of the settings language switcher (§4.3).
class LocaleChoice {
  const LocaleChoice(this.code, this.nativeLabel);

  /// Stored preference code ('en'/'am'/'om'); null = follow system.
  final String? code;

  /// Display label in the language's own script.
  final String nativeLabel;
}

/// Convenience accessor used across the nidus module (§4.3 extraction pass).
extension AppLocalizationsX on BuildContext {
  AppLocalizations get l10n => AppLocalizations.of(this);
}
